BEGIN;

-- ユウの依頼「python問題集は他の問題も全体的にわかりやすくしてほしいのと、
-- 特徴的な処理はその処理の行ごとにどんな出力になるかもわかりやすく」に対応。
-- q19/q26/q43/q44/q56/q88(実メモ由来の個別修正)を除く86問を6並列エージェントで
-- 監査し、64問に改善を適用（主にcalcキーで1行/1ステップずつのトレースを追加）。
-- 非破壊マージ：既存キーは上書き、それ以外は保持。
UPDATE public.questions q
SET explanation_data = q.explanation_data || v.value
FROM jsonb_each('{"python-drill-q01": {"calc": "1行ずつ確かめる。\n\nitems = [''a'', ''b'', ''c'']\n.append(''d'') → 末尾に''d''を追加 → items = [''a'', ''b'', ''c'', ''d'']\n.pop() → 引数なしなので末尾の要素を取り出して削除 → 取り出したのは''d'' → items = [''a'', ''b'', ''c''], removed = ''d''\n\nprint(items, removed) → [''a'', ''b'', ''c''] d"}, "python-drill-q02": {"calc": "1行ずつ確かめる。\n\nnums = [10, 20, 30]\n.insert(1, 15) → インデックス1の位置に15を挿入（元のインデックス1以降は後ろにずれる）→ nums = [10, 15, 20, 30]\n.remove(30) → 値30を探して削除 → nums = [10, 15, 20]\n\nprint(nums) → [10, 15, 20]"}, "python-drill-q03": {"calc": "1つずつ確かめる。\n\ns = [0, 1, 2, 3, 4, 5]（インデックスは0,1,2,3,4,5）\n\ns[1:4] → インデックス1から3まで（4は含まない）→ [1, 2, 3]\ns[-2:] → 後ろから2番目（インデックス4）から末尾まで → [4, 5]\ns[::2] → インデックス0から2つおき（0, 2, 4）→ [0, 2, 4]\n\nprint(s[1:4], s[-2:], s[::2]) → [1, 2, 3] [4, 5] [0, 2, 4]"}, "python-drill-q04": {"calc": "1行ずつ確かめる。\n\n1行目: user.get(\"age\", 0) → \"age\"というキーはuserに無い → デフォルト値0を返す（エラーにはならない）→ 0が表示される\n2行目: user[\"age\"] → 角括弧アクセスには「無ければデフォルト値」という仕組みが無い → \"age\"キーが無いのでその場でKeyErrorが発生し、プログラムはそこで止まる\n\nつまり出力は「0」の後に「KeyErrorで異常終了」となる。"}, "python-drill-q05": {"calc": "1周ずつ確かめる。\n\nprices = {\"tea\": 300, \"coffee\": 400}（辞書は挿入した順番を覚えている）\n\n1周目: k=\"tea\", v=300 → print(\"tea\", 300) → tea 300\n2周目: k=\"coffee\", v=400 → print(\"coffee\", 400) → coffee 400\n\nつまり出力は\ntea 300\ncoffee 400\nの2行になる。"}, "python-drill-q06": {"calc": "1行ずつ確かめる。\n\nline = \"apple,banana,,cherry\"\n.split(\",\") → カンマの位置で切る。bananaの次のカンマとcherryの前のカンマの間には何も文字が無いので、そこは空文字''''という1つの要素になる → parts = [''apple'', ''banana'', '''', ''cherry'']\n\n\"-\".join(parts) → 各要素の間に''-''を挟んでつなげる\n''apple'' + ''-'' + ''banana'' + ''-'' + '''' + ''-'' + ''cherry''\n→ ''banana''と''''の間、''''と''cherry''の間にそれぞれ''-''が入るので、空文字の前後で''-''が連続し''--''に見える\n→ ''apple-banana--cherry''"}, "python-drill-q08": {"calc": "1周ずつ確かめる。range(2, 10, 3)はstart=2, stop=10, step=3。\n\n1周目: i=2（10未満）→ print(2)\n2周目: i=2+3=5（10未満）→ print(5)\n3周目: i=5+3=8（10未満）→ print(8)\n4周目: i=8+3=11 → 11は10未満ではないのでループ終了（11は出力されない）\n\nつまり出力は\n2\n5\n8\nの3行になる。"}, "python-drill-q09": {"calc": "1行ずつ確かめる。\n\n1行目: \"banana\" in fruits → fruitsは[''apple'', ''banana'']というリスト。要素として''banana''が完全一致で存在するか調べる → 存在する → True\n\n2行目: \"banana\" in \"I like bananas\" → 文字列の中に''banana''という並びが部分文字列として含まれているか調べる → ''bananas''の中に''banana''が含まれている → True\n\nつまり出力は\nTrue\nTrue\nの2行になる。"}, "python-drill-q10": {"calc": "1行ずつ確かめる。\n\nconfig = {\"debug\": False, \"retries\": 3}\n.update({\"retries\": 5, \"timeout\": 10}) → 既存キー\"retries\"の値を3から5に上書き、無かった\"timeout\"を新しく追加 → config = {\"debug\": False, \"retries\": 5, \"timeout\": 10}\n.pop(\"debug\") → \"debug\"キーを削除し、削除した値Falseを返す → config = {\"retries\": 5, \"timeout\": 10}, removed = False\n\nprint(config, removed) → {''retries'': 5, ''timeout'': 10} False"}, "python-drill-q11": {"calc": "1行ずつ確かめる。\n\na = [1, 2]\na.append([3, 4]) → [3, 4]というリストそのものを1つの要素として追加 → a = [1, 2, [3, 4]]（リストの中にリストが入れ子になる）\n\nb = [1, 2]\nb.extend([3, 4]) → [3, 4]の中身3と4を1つずつ展開して追加 → b = [1, 2, 3, 4]（ネストしないフラットなリスト）\n\nprint(a, b) → [1, 2, [3, 4]] [1, 2, 3, 4]"}, "python-drill-q12": {"calc": "1行ずつ確かめる（順番が大事）。\n\nnums = [3, 1, 2]\n\nresult = sorted(nums) → numsは変えずに、昇順に並べた「新しいリスト」を作ってresultに代入 → result = [1, 2, 3]（この時点でresultは完成済みの独立したコピー）\n\nnums.sort(reverse=True) → nums自身を降順に並び替える（戻り値はNoneなので使わない）→ nums = [3, 2, 1]\n\nresultは1行目の時点で既に独立したコピーとして出来上がっているので、後からnumsを並び替えてもresultには影響しない\n\nprint(nums, result) → [3, 2, 1] [1, 2, 3]"}, "python-drill-q13": {"calc": "1行ずつ確かめる。\n\ns = \"hello world\"\n\n1行目: s.find(\"z\") → \"z\"は見つからないが、find()はエラーを出さない設計なので-1を返す → -1が表示される\n2行目: s.index(\"z\") → \"z\"は見つからないと、index()はその場でValueErrorを送出する設計 → プログラムはそこで異常終了する\n\nつまり出力は「-1」の後に「ValueErrorで異常終了」となる。"}, "python-drill-q14": {"calc": "1つずつ確かめる。\n\na = {1, 2, 3}, b = {2, 3, 4}\n\na & b（積集合）→ 両方に共通する要素 → 2は両方にある、3は両方にある、1と4はどちらか片方だけ → {2, 3}\na | b（和集合）→ 両方の要素を全部合わせる → {1, 2, 3, 4}\na - b（差集合）→ aにあってbに無い要素 → 1はaにあってbに無い、2と3は両方にあるので除外 → {1}\n\nprint(a & b, a | b, a - b) → {2, 3} {1, 2, 3, 4} {1}"}, "python-drill-q16": {"calc": "1つずつ順番に確かめる。\n\nn=1 → 1 % 2 == 0 ? いいえ(奇数) → 除外\nn=2 → 2 % 2 == 0 ? はい → 2*2=4 → 採用\nn=3 → 3 % 2 == 0 ? いいえ(奇数) → 除外\nn=4 → 4 % 2 == 0 ? はい → 4*4=16 → 採用\nn=5 → 5 % 2 == 0 ? いいえ(奇数) → 除外\nn=6 → 6 % 2 == 0 ? はい → 6*6=36 → 採用\n\n採用されたものを順番に並べると: [4, 16, 36]"}, "python-drill-q17": {"calc": "1つずつ順番に確かめる。\n\nw=\"a\" → len(\"a\") = 1 → キー\"a\"に値1を対応させる\nw=\"bb\" → len(\"bb\") = 2 → キー\"bb\"に値2を対応させる\nw=\"ccc\" → len(\"ccc\") = 3 → キー\"ccc\"に値3を対応させる\n\nできあがった辞書: {''a'': 1, ''bb'': 2, ''ccc'': 3}"}, "python-drill-q18": {"calc": "1つずつ「比較に使う値」を取り出してから並べ替える。\n\n(\"Yu\", 34) → 比較に使う値(年齢) = 34\n(\"Kei\", 29) → 比較に使う値(年齢) = 29\n(\"Rio\", 41) → 比較に使う値(年齢) = 41\n\n取り出した年齢を小さい順に並べる: 29 → 34 → 41\nその順番のまま元のタプルを並べ直すと: [(''Kei'', 29), (''Yu'', 34), (''Rio'', 41)]"}, "python-drill-q20": {"calc": "zip(names, scores)がまず同じ位置どうしをペアにする。\n\n1組目: (\"a\", 90)\n2組目: (\"b\", 80)\n3組目: (\"c\", 70)\n\n次にenumerate()が0から順に番号を振りながら、forの(n, s)がそのペアを分解して受け取る。\n\ni=0のとき: ペア(\"a\", 90) → n=\"a\", s=90 → \"0 a 90\"\ni=1のとき: ペア(\"b\", 80) → n=\"b\", s=80 → \"1 b 80\"\ni=2のとき: ペア(\"c\", 70) → n=\"c\", s=70 → \"2 c 70\"\n\n問われているのは「最初に出力される行」なので、i=0の \"0 a 90\" が答え。"}, "python-drill-q22": {"calc": "呼び出しを1回ずつ追う。\n\n【関数定義の瞬間】bucket=[]の空リストが1個だけ作られる（以後ずっとこの同じリストを使い回す）。\n\n【1回目: add_item(\"x\")】\n・bucketは定義時に作られたあの空リスト[]\n・bucket.append(\"x\") → bucketは[''x'']になる\n・戻り値: [''x''] → 1行目の出力は [''x'']\n\n【2回目: add_item(\"y\")】\n・引数bucketを省略しているので、また同じあの1個だけのリストが使われる（すでに[''x'']になっている）\n・bucket.append(\"y\") → bucketは[''x'', ''y'']になる\n・戻り値: [''x'', ''y''] → 2行目の出力は [''x'', ''y'']\n\n「毎回呼び出すたびに新しい空リストから始まる」と思っていると、2回目も[''y'']だけになると誤解してしまう。"}, "python-drill-q23": {"calc": "3つの比較を1つずつ確かめる。\n\na == b → aとbは中身(要素)がどちらも[1, 2, 3]で同じ → True\na is b → aとbは別々に作られた「別のリストオブジェクト」（中身が同じでも実体は別） → False\na is c → c = aによってcはaと同じ実体を指しているだけ（新しいリストは作られていない） → True\n\n出力は True False True。"}, "python-drill-q24": {"calc": "ステップごとに何が起きているか確かめる。\n\n1. original = [[1, 2], [3, 4]] → 外側のリストの中に、[1, 2]と[3, 4]という2つの内側リストが入っている\n2. shallow = original.copy() → 外側の入れ物だけ新しく複製される。ただし中の[1, 2]と[3, 4]自体は複製されず、originalとshallowの両方が同じ[1, 2]・同じ[3, 4]を指したままになる\n3. shallow[0].append(99) → shallow[0]が指しているのは、original[0]と共有している同じ[1, 2]というオブジェクト。そこに99を追加するので、そのオブジェクト自体が[1, 2, 99]に変わる\n4. originalから見ても、original[0]は同じオブジェクトを指しているので、original[0]も[1, 2, 99]に見える\n\nだからprint(original)の結果は [[1, 2, 99], [3, 4]]。"}, "python-drill-q27": {"calc": "左から順に対応させる。\n\nfirst ← 先頭の95\nlast ← 末尾の40\n*middle ← firstとlastに割り当てた残り全部 → [60, 70, 85]\n\n出力は 95 [60, 70, 85] 40。"}, "python-drill-q28": {"calc": "all(...)を順番に確かめる（1つでも条件を満たさなければ、その時点で判定を打ち切る＝短絡評価）。\n\nn=2 → 2 % 2 == 0 ? はい → 続行\nn=4 → 4 % 2 == 0 ? はい → 続行\nn=6 → 6 % 2 == 0 ? はい → 続行\nn=7 → 7 % 2 == 0 ? いいえ → ここで条件が崩れたのでall(...)は即座にFalseと判定（残りの8は確認しない）\n\nany(...)を順番に確かめる（1つでも条件を満たせば、その時点で判定を打ち切る＝短絡評価。今回は最後まで見ても見つからない）。\n\nn=2 → 2 > 10 ? いいえ\nn=4 → 4 > 10 ? いいえ\nn=6 → 6 > 10 ? いいえ\nn=7 → 7 > 10 ? いいえ\nn=8 → 8 > 10 ? いいえ → 最後まで条件を満たす要素が無かったのでany(...)はFalse\n\n出力は False の後に False。"}, "python-drill-q29": {"calc": "1つずつ確かめる。\n\ns=40 → 40 >= 60 ? いいえ → \"fail\"\ns=60 → 60 >= 60 ? はい（60は含まれる） → \"pass\"\ns=80 → 80 >= 60 ? はい → \"pass\"\n\n順番に並べると: [''fail'', ''pass'', ''pass'']"}, "python-drill-q32": {"calc": "1つずつ順番に確かめる。\n\nv=0 → bool(0) → False\nv=1 → bool(1) → True\nv=\"\" → bool(\"\") → False（空文字はfalsy）\nv=\"a\" → bool(\"a\") → True（中身のある文字列はtruthy）\nv=[] → bool([]) → False（空リストはfalsy）\nv=[1] → bool([1]) → True（要素が1つでもあればtruthy）\nv=None → bool(None) → False\n\nend=\" \"で改行せず横並びに出すので、結果は「False True False True False True False」という並びになる。"}, "python-drill-q33": {"calc": "while文を1周ずつ、iの値を追って確かめる。\n\n①周目: i=0→i+=1でi=1。1は偶数でない、1は5でもない→print(1)を実行。\n②周目: i=1→i+=1でi=2。2は偶数→continueでこの周のprintはスキップ。\n③周目: i=2→i+=1でi=3。3は偶数でない、3は5でもない→print(3)を実行。\n④周目: i=3→i+=1でi=4。4は偶数→continueでこの周のprintはスキップ。\n⑤周目: i=4→i+=1でi=5。5は偶数でない、5は5なのでbreak。breakはprint(i, ...)より前に書かれているため、このi=5はprintされないままループを抜ける。\n\n実際にprintされたのは①周目の1と③周目の3だけなので、出力は「1 3」。"}, "python-drill-q35": {"calc": "内包表記で1語ずつ頭文字を確かめ、setに集めていく。\n\n\"apple\" → 先頭は''a'' → setに追加 → {''a''}\n\"banana\" → 先頭は''b'' → setに追加 → {''a'', ''b''}\n\"avocado\" → 先頭は''a'' → すでにsetにあるので変化なし → {''a'', ''b''}\n\"kiwi\" → 先頭は''k'' → setに追加 → {''a'', ''b'', ''k''}\n\n最終的なsetは{''a'', ''b'', ''k''}（3要素）。sorted()でアルファベット順のリストにすると[''a'', ''b'', ''k'']。"}, "python-drill-q36": {"calc": "リストの要素を先頭から1個ずつ数えていく。\n\n1個目\"a\" → a:1\n2個目\"b\" → b:1\n3個目\"a\" → a:2\n4個目\"c\" → c:1\n5個目\"b\" → b:2\n6個目\"a\" → a:3\n\n最終的な内訳はa:3, b:2, c:1。most_common(2)は回数の多い順に上位2件を(値, 回数)のタプルで返すので[(''a'', 3), (''b'', 2)]。"}, "python-drill-q37": {"calc": "単語を1つずつ処理して、頭文字のキーへappendしていく。\n\n\"ant\" → キー''a''はまだ無い→defaultdictが自動で空リストを用意→[''ant'']を追加後、groups[''a'']=[''ant'']\n\"bee\" → キー''b''はまだ無い→自動で空リストを用意→groups[''b'']=[''bee'']\n\"ape\" → キー''a''は既にある→そのリストに追加→groups[''a'']=[''ant'', ''ape'']\n\"bat\" → キー''b''は既にある→そのリストに追加→groups[''b'']=[''bee'', ''bat'']\n\n最終的にgroups（dictに変換して表示）は{''a'': [''ant'', ''ape''], ''b'': [''bee'', ''bat'']}。"}, "python-drill-q38": {"calc": "chain()はa→b→cの順に、それぞれの中身を1つずつ取り出してつなげる。\n\naから: 1, 2\nbから: 3, 4\ncから（文字列は1文字ずつのイテラブル）: ''5'', ''6''\n\n全部つなげてlist化すると[1, 2, 3, 4, ''5'', ''6'']。"}, "python-drill-q39": {"calc": "try文の4パーツがどの順で動くかを追う。\n\n①tryブロックを実行: result = 10 / 2 = 5.0（例外は発生しない）\n②exceptブロックは例外が起きていないのでスキップ\n③elseブロックを実行（tryが例外なく終わったときだけ実行される）: print(\"ok:\", result) → \"ok: 5.0\"\n④finallyブロックを実行（例外の有無に関係なく必ず実行される）: print(\"done\") → \"done\"\n\n出力の順番は「ok: 5.0」の後に「done」。"}, "python-drill-q40": {"point": "インスタンス変数はself.属性名で保持され、メソッド呼び出しをまたいで値が引き継がれる。さらにprint()の引数は左から右へ順番に評価されるため、1つ目のc.increment()が先に実行されて1、2つ目が2になる。", "calc": "print()の引数は書かれた順（左から右）に評価されてから呼び出される。\n\n①1つ目のc.increment()を実行 → self.valueが0→1に増える → 1を返す\n②2つ目のc.increment()を実行 → self.valueが1→2に増える → 2を返す\n③print(1, 2)が実行される\n\n出力は「1 2」。"}, "python-drill-q41": {"calc": "@shoutが付いたgreet(\"yu\")の呼び出しを、実際に動く順番で追う。\n\n①greet(\"yu\")を呼ぶ→実体はwrapper(\"yu\")が呼ばれる（args=(\"yu\",)）\n②wrapperの中でresult = func(\"yu\")を実行→funcは元のgreet関数→f\"hello, {name}\"で\"hello, yu\"を作って返す\n③resultは\"hello, yu\"\n④return result.upper()を実行→\"hello, yu\".upper()→\"HELLO, YU\"\n⑤呼び出し元のprint()が\"HELLO, YU\"を受け取って出力する\n\n出力は「HELLO, YU」。"}, "python-drill-q42": {"calc": "next()を呼ぶたびに、直前のyieldの次の行から再開する様子を1回ずつ追う。\n\n①gen = countdown(3)の時点では関数の中身はまだ1行も実行されていない（呼び出しただけではジェネレータオブジェクトができるだけ）\n②1回目のnext(gen)→関数の先頭から実行開始→n=3、while 3>0はTrue→yield nでそこに印を付けて一時停止し3を返す\n③2回目のnext(gen)→さっき止まったyieldの次から再開→n -= 1でn=2→whileの先頭に戻り2>0はTrue→yield nで一時停止し2を返す\n④list(gen)は、生成が止まるまでnext()を繰り返す→再開してn -= 1でn=1→1>0はTrue→yield nで1を生成しリストに追加→さらに次のnext()相当で再開しn -= 1でn=0→0>0はFalseでwhileを抜け関数が終了（StopIteration）→list(gen)が受け取れたのは1だけなので[1]\n\n出力はnext(gen)の1回目が3、2回目が2、list(gen)が[1]で、順に「3 → 2 → [1]」。"}, "python-drill-q44": {"calc": "doubleとtripleは別々の呼び出しで作られるので、それぞれの計算を分けて追う。\n\ndouble = make_multiplier(2) → 内側のmultiplyがfactor=2を覚えたまま返される\ntriple = make_multiplier(3) → 別のmultiplyがfactor=3を覚えたまま返される\ndouble(5) → 5 * 2 = 10\ntriple(5) → 5 * 3 = 15\n\nprint(double(5), triple(5))の出力は「10 15」。"}, "python-drill-q45": {"calc": "c()を呼ぶたびに、外側のcountがどう変わるかを1回ずつ追う。\n\nmake_counter()を1回呼んだ時点でcount=0が用意され、それをincrementが「覚えたまま」cとして返される。\n\n①1回目のc() → nonlocal countによりcountを書き換え可能→count 0→1→1を返す\n②2回目のc() → 前回の続きからcount 1→2→2を返す\n③3回目のc() → count 2→3→3を返す\n\nprint()の引数は左から順に呼び出されるので、print(c(), c(), c())の出力は「1 2 3」。"}, "python-drill-q46": {"usecase": "実務での使い分けの目安: ①@staticmethodは「そのクラスに関係はあるけど、インスタンスの状態もクラス変数も使わない独立した計算・変換処理」に使う。例: 温度の単位変換、入力値のバリデーションなど、クラス名の下に整理しておきたいだけの普通の関数。②@classmethodは「クラス変数を読み書きしたい」「通常の__init__とは違う作り方でインスタンスを生成したい（別コンストラクタ）」ときに使う。例: Point.from_dict(d)のように、辞書やCSVの1行など別の入力形式からインスタンスを組み立てる工場メソッドによく使われる。"}, "python-drill-q47": {"calc": "1行ずつ例外の流れを追う。\n\nparse(\"abc\") が呼ばれる\n  → int(\"abc\") で ValueError が発生\n  → except ValueError as e で捕まえる（e = そのValueErrorオブジェクト）\n  → raise RuntimeError(\"parse failed\") from e で新しい例外を送出\n     このとき新しいRuntimeErrorの __cause__ に元のValueError（e）が記録される\n  → parse() の外まで、このRuntimeErrorが伝播していく\n\n外側の except RuntimeError as err で捕まえる\n  → err は RuntimeError\n  → err.__cause__ は元の ValueError\n\nprint(type(err).__name__, \"<-\", type(err.__cause__).__name__)\n  → \"RuntimeError\" と \"ValueError\" を \"<-\" でつないで表示\n  → RuntimeError <- ValueError"}, "python-drill-q49": {"calc": "1行ずつ「箱」の状態を追う。\n\na = [1, 2, 3]     → aは[1, 2, 3]という箱\nb = a             → bはaと同じ箱を指す（別名。新しい箱は作られない）\nc = a[:]          → cは中身だけコピーした別の箱: [1, 2, 3]\nb.append(4)       → b(=aと同じ箱)に4を追加 → aは[1, 2, 3, 4]になる\nc.append(5)       → c(別の箱)に5を追加 → cは[1, 2, 3, 5]になる（aには影響しない）\n\nprint(a, c) → [1, 2, 3, 4] [1, 2, 3, 5]"}, "python-drill-q50": {"calc": "1行ずつ「外側の箱」と「内側の箱」を分けて追う。\n\noriginal = [[1, 2], [3, 4]]     → original: [[1, 2], [3, 4]]\nshallow = copy.copy(original)   → shallowは新しく作られた外側の箱。ただし中の[1, 2]と[3, 4]はoriginalと共有されたまま\nshallow.append([5, 6])          → shallowという外側の箱だけに[5, 6]を追加（外側は独立なのでoriginalは変わらない）\nshallow[0][0] = 99               → 共有している内側の[1, 2]そのものを書き換える → originalの1つ目の要素も99になる\n\nprint(original) → [[99, 2], [3, 4]]\nprint(shallow)  → [[99, 2], [3, 4], [5, 6]]"}, "python-drill-q51": {"calc": "1行ずつ状態を追う。\n\noriginal = [[1, 2], [3, 4]]      → original: [[1, 2], [3, 4]]\ndeep = copy.deepcopy(original)   → deepは外側も内側も全部新しく複製された、originalとは無関係の別物\ndeep[0][0] = 99                  → deepだけが持つ独立した[1, 2]を書き換える → originalには一切影響しない\n\nprint(original) → [[1, 2], [3, 4]]\nprint(deep)     → [[99, 2], [3, 4]]"}, "python-drill-q54": {"calc": "1行ずつ実行の順番を追う（ジェネレータは呼んだだけでは動かない点に注意）。\n\ng = steps()        → ジェネレータオブジェクトが作られるだけ。中身はまだ1行も実行されない\nprint(\"created\")   → 画面に \"created\" と出る\nvalue = next(g)     → ここで初めて関数の中身が動き出す\n  ① print(\"A\") が実行される → 画面に \"A\" と出る\n  ② yield 1 で実行がいったん止まり、1が呼び出し側に返る → value に 1 が入る\nprint(value)        → 画面に \"1\" と出る\n\n出力順: created → A → 1"}, "python-drill-q55": {"calc": "1行ずつジェネレータの「残り」を追う。\n\ng = (x for x in [1, 2, 3])   → gのカーソルは先頭（何も取り出していない）\n1回目 print(list(g))\n  → 先頭から1, 2, 3を順に取り出す → gは空になる\n  → 結果: [1, 2, 3]\n2回目 print(list(g))\n  → gはすでに空。取り出せる値が残っていない\n  → 結果: []"}, "python-drill-q57": {"calc": "next(g) - next(g) を左から順に評価する。\n\n1回目のnext(g) → yield 10 まで進み、10を返す（gの状態はここで一時停止）\n2回目のnext(g) → 続きから yield 3 まで進み、3を返す\n\n10 - 3 = 7"}, "python-drill-q58": {"calc": "next(g)を呼ぶたびに、gの状態が1つずつ先に進む。\n\n1回目のnext(g) → yield 1 まで進み、1を返す → print → \"1\"\n2回目のnext(g) → yield 2 まで進み、2を返す → print → \"2\"　（この時点でgは持っているyieldを使い切った）\n3回目のnext(g) → もう進める先のyieldが無い → StopIteration が発生してそこで処理が止まる"}, "python-drill-q59": {"calc": "ジェネレータ式が1つずつ値を作り、sum()がそれを順に受け取って足していく。\n\nx=1 → x*x = 1\nx=2 → x*x = 4\nx=3 → x*x = 9\nx=4 → x*x = 16\n\nsum(1, 4, 9, 16) = 1+4+9+16 = 30"}, "python-drill-q60": {"calc": "1行ずつ実行を追う（例外がどこを通ってどこに落ち着くか）。\n\nn = int(\"abc\")            → 変換に失敗 → ValueError発生 → tryブロックの残りはスキップされる\nexcept ValueError:        → 捕まえる → print(\"invalid\") が実行される\nelse:                     → 例外が起きたのでこの節は実行されない（スキップ）\nfinally:                  → 例外の有無にかかわらず必ず実行される → print(\"checked\") が実行される\n\n出力順: invalid → checked"}, "python-drill-q61": {"calc": "上から順にexcept節を確認する。\n\ndivide(10, 0) を呼ぶ → a/b は 10/0 → ZeroDivisionError が発生\n\n1つ目の except Exception を確認 → ZeroDivisionError は Exception のサブクラス（Exceptionという大きな分類に含まれる、より具体的な種類）なのでここでマッチ → \"generic\" を return\n\n2つ目の except ZeroDivisionError は確認されない（1つ目のexcept節でreturnが実行され、処理がそこで終わっているため）\n\n→ 出力は \"generic\""}, "python-drill-q63": {"calc": "validate(-5) を呼ぶ\n\n1. n < 0 は True → raise ValueError(\"negative\")\n2. 内側の except ValueError がキャッチ → print(\"caught inside\")\n3. raise（引数なし）→ 今キャッチ中の ValueError(\"negative\") をそのまま外へ投げ直す\n4. validate関数の外に例外が伝播する\n5. 外側の except ValueError as e がキャッチ → eには\"negative\"が入っている → print(\"caught outside:\", e)\n\n→ 出力は \"caught inside\" の次に \"caught outside: negative\""}, "python-drill-q65": {"calc": "safe_calc(10, 0) を呼ぶ\n\n1. tryの中で risky_division(10, 0) を呼ぶ\n2. risky_divisionの中で a/b → 10/0 → ZeroDivisionErrorが発生（risky_division自身にはtryが無い）\n3. 例外はそのままrisky_divisionの外（呼び出し元）へ伝播する\n4. この呼び出しはsafe_calcのtryブロックの中で行われているので、safe_calcのexcept ZeroDivisionErrorがキャッチする\n5. print(\"caught in safe_calc\")\n\n※ 例外はresult = risky_division(a, b)の代入が完了する前に発生するので、resultへの代入もprint(\"result:\", result)も実行されない\n\n→ 出力は \"caught in safe_calc\" のみ"}, "python-drill-q66": {"calc": "呼び出しごとに、共有のデフォルトリストがどう変化するかを追う。\n\n1. collect(1) → lstを省略 → デフォルトの共有リスト（最初は[]）を使う → append(1) → 共有リストは[1]に（printしていないので画面には出ない）\n\n2. print(collect(2, [])) → 明示的に新しい空リスト[]を渡す → これは共有リストとは別物 → append(2) → [2] ←これが出力される（共有リストは[1]のまま変化なし）\n\n3. print(collect(3)) → 再びlstを省略 → デフォルトの共有リスト（まだ[1]）を使う → append(3) → [1, 3] ←これが出力される\n\n→ 出力は [2] の次に [1, 3]"}, "python-drill-q69": {"calc": "1. counter = [1, 2, 3] → counterは[1, 2, 3]\n2. def describe(x=len(counter)): が実行される瞬間、デフォルト値の式len(counter)がここで1回だけ評価される → 3 → xのデフォルト値として固定される\n3. counter.append(4) → counterは[1, 2, 3, 4]に変化（固定済みのデフォルト値3には無関係）\n4. counter.append(5) → counterは[1, 2, 3, 4, 5]に変化（デフォルト値はまだ3のまま）\n5. describe() を呼ぶ → xを省略 → 固定済みの3が使われる → \"x is 3\"\n\n→ 出力は \"x is 3\""}, "python-drill-q71": {"calc": "各人物を (-年齢, 名前) というタプルに変換してから比較する。\n\nYu  → (-34, ''Yu'')\nKei → (-29, ''Kei'')\nRio → (-34, ''Rio'')\n\nsorted()はこのタプルを小さい順に並べる。\n1番目の要素(-年齢)で比較 → -34 < -29 なので、年齢34の2人(Yu, Rio)が先、年齢29のKeiが最後\n年齢34の2人は1番目の要素が同点(-34)なので、2番目の要素(名前)で比較 → ''Rio'' < ''Yu'' なのでRioが先\n\n→ 並び順は [(''Rio'', 34), (''Yu'', 34), (''Kei'', 29)]"}, "python-drill-q72": {"calc": "result1（初期値なし。先頭要素の1から開始）\nacc=1（開始）\nx=2 → acc = 1*2 = 2\nx=3 → acc = 2*3 = 6\nx=4 → acc = 6*4 = 24\n→ result1 = 24\n\nresult2（初期値0を指定）\nacc=0（開始）\nx=1 → acc = 0*1 = 0\nx=2 → acc = 0*2 = 0\nx=3 → acc = 0*3 = 0\nx=4 → acc = 0*4 = 0\n→ result2 = 0\n\n→ 出力は \"24 0\""}, "python-drill-q73": {"calc": "any()は要素を1つずつ確かめ、Trueが見つかった時点で打ち切る。\n\nn=1 → check(1)を呼ぶ → \"check(1)\"を表示 → 1>2 はFalse → 次へ\nn=2 → check(2)を呼ぶ → \"check(2)\"を表示 → 2>2 はFalse → 次へ\nn=3 → check(3)を呼ぶ → \"check(3)\"を表示 → 3>2 はTrue → ここでany()の結果が確定、打ち切り\nn=4 → 評価されない（check(4)は呼ばれない）\n\n→ any()の戻り値はTrue。出力は \"check(1)\" → \"check(2)\" → \"check(3)\" → \"True\""}, "python-drill-q74": {"calc": "1回目のlist(doubled) → イテレータを先頭から最後まで読み進める → 1→2, 2→4, 3→6 → [2, 4, 6] ←出力\n\n2回目のlist(doubled) → doubledはすでに最後まで読み切られていて、残っている要素が無い → [] ←出力\n\n→ 出力は [2, 4, 6] の次に []"}, "python-drill-q76": {"calc": "1. msg = \"hello\" → msgは文字列\"hello\"を指す\n2. add_exclaim(msg)を呼ぶ → 関数内のtextは最初、msgと同じ\"hello\"を指している\n3. text += \"!\" → 文字列はイミュータブル（一度作ったら中身を直接書き換えられない性質）なので、\"hello\"自体を書き換えるのではなく新しい文字列\"hello!\"を作り、textだけがそれを指すようになる → msgは元の\"hello\"を指したまま変化しない\n4. return textで\"hello!\"が返り、resultに代入される\n5. print(msg, result) → msgは\"hello\"のまま、resultは\"hello!\"\n\n→ 出力は \"hello hello!\""}, "python-drill-q77": {"terms": [[".strip()", "文字列の前後の空白を取り除いた新しい文字列を返す。元の文字列は変更しない"], [".replace(old, new)", "oldをnewに置き換えた新しい文字列を返す。元の文字列は変更しない"], ["repr(text)", "文字列を引用符付きでそのまま表示する関数。前後の空白の有無がわかりやすい"], ["イミュータブル", "一度作った後は中身を直接書き換えられない性質。文字列やタプルがこれに当たり、変更したいときは新しい値を作って変数に代入し直すしかない"]]}, "python-drill-q83": {"calc": "①counter()が呼ばれ、ローカル変数countが0で作られる。\n②1回目のincrement()呼び出し: nonlocal countなのでcounter側のcountを直接操作する。count += 1でcountは0→1になる（戻り値は1だが使われていない）。\n③2回目のincrement()呼び出し: 同じcounter側のcountを再び操作し、1→2になる。\n④print(count)はcounter自身のcountを参照するので、2回分の増加を反映した2が出力される。"}, "python-drill-q86": {"calc": "①print(greet())が実行されると、greetの実体であるwrapper()が呼ばれる。\n②wrapperの中でfunc()（＝元のgreet）を呼び出し、戻り値''hello''を受け取る。\n③''hello''.upper()で''HELLO''に変換する。\n④wrapperがreturnで''HELLO''をprintに渡し、画面に''HELLO''が出力される。"}, "python-drill-q87": {"kid": "task()を呼ぶと、実際にはwrapper()が動く。wrapperはまず''start''を表示し、その後にfunc()＝元のtaskを実行して''working''を表示し、最後に''end''を表示する。だから1行目start、2行目working、3行目endの順で出力される。", "calc": "①wrapper()の1行目print(''start'')が実行され、1行目に''start''が出力される。\n②func()（＝元のtask）が呼ばれ、その中のprint(''working'')が実行されて2行目に''working''が出力される。\n③task側の処理が終わってwrapperに戻り、3行目のprint(''end'')が実行されて3行目に''end''が出力される。"}, "python-drill-q89": {"calc": "デコレータの適用（定義するときに実際に起きる順。上から読める順ではない）:\n①関数に一番近い@italicが先に効き、text = italic(text) が実行されてtextの中身はitalic用wrapperになる。\n②続けて@boldが効き、text = bold(text) が実行されてtextの中身は今度はbold用wrapper（内側にitalic用wrapperを持つ）になる。\n\n呼び出し（print(text())を実行したとき）:\n③外側のbold用wrapperがまず動き出し、中のfunc()＝italic用wrapperを呼ぶ。\n④italic用wrapperが元のtext()を呼んで''hi''を受け取り、''<i>hi</i>''にして返す。\n⑤bold用wrapperがその''<i>hi</i>''を受け取り、''<b><i>hi</i></b>''にして返す。これが最終的な出力。"}, "python-drill-q90": {"calc": "①with Resource(): に入る瞬間に__enter__が呼ばれ、1行目に''open''が出力される。\n②withブロックの中身print(''using'')が実行され、2行目に''using''が出力される。\n③withブロックを抜けるときに__exit__が呼ばれ、3行目に''close''が出力される。"}, "python-drill-q91": {"calc": "①with Resource(): に入る瞬間に__enter__が呼ばれ、1行目に''open''が出力される。\n②withブロックの中でprint(''using'')が実行され、2行目に''using''が出力される。\n③直後のraise ValueError(\"boom\")で例外が発生する。\n④例外が起きてもwithは__exit__を必ず呼ぶという保証があるので、__exit__が実行され3行目に''close''が出力される。\n⑤__exit__の戻り値はFalseなので、例外は揉み消されずそのまま外側へ伝わり続ける。\n⑥外側のtry/exceptがValueErrorを受け取り、4行目に''caught''が出力される。"}, "python-drill-q92": {"calc": "①with resource() as r: に入ると、resource()の実行がyieldの手前まで進み、1行目に''open''が出力される。\n②yield \"handle\"で実行がいったん止まり、''handle''という値がasの右辺rに渡される。\n③withブロックの中身print(''using'', r)が実行され、2行目に''using handle''が出力される。\n④withブロックを抜けると、止まっていたyieldの続きから実行が再開し、3行目に''close''が出力される。"}}'::jsonb) AS v(key, value)
WHERE q.source_ref = v.key
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'python-drill')
  AND q.explanation_data IS NOT NULL;

COMMIT;
